import pandas as pd
import numpy as np

def _as_mapping(obj):
    if isinstance(obj, pd.Series):
        return obj.to_dict()
    if isinstance(obj, dict):
        return obj
    return {}

def _find_value(src, aliases):
    m = _as_mapping(src)
    lower_map = {str(k).lower(): k for k in m.keys()}
    for a in aliases:
        if a.lower() in lower_map:
            return m[lower_map[a.lower()]]
    for k, v in m.items():
        kl = str(k).lower()
        if any(a.lower() in kl for a in aliases):
            return v
    raise KeyError(aliases)

def _has_value(src, aliases):
    try:
        v = _find_value(src, aliases)
        return pd.notna(v)
    except Exception:
        return False

def _first_valid_source(candidates, aliases):
    for src in candidates:
        if _has_value(src, aliases):
            return src
    raise KeyError(aliases)

