import pandas as pd
import numpy as np

def _iter_sources(*objs):
    out = []
    for obj in objs:
        if obj is None:
            continue
        if isinstance(obj, dict):
            out.append(obj)
            for v in obj.values():
                if isinstance(v, (dict, pd.Series)):
                    out.append(v)
        elif isinstance(obj, pd.Series):
            out.append(obj)
    return out

def _mapping(obj):
    if isinstance(obj, pd.Series):
        return obj.to_dict()
    if isinstance(obj, dict):
        return obj
    return {}

def _numeric_or_none(v):
    try:
        if pd.isna(v):
            return None
        return float(v)
    except Exception:
        return None

def _get_value(sources, exact_keys, fallback_contains=(), exclude_contains=(), require_numeric=False):
    exact_l = [k.lower() for k in exact_keys]
    fallback_l = [k.lower() for k in fallback_contains]
    exclude_l = [k.lower() for k in exclude_contains]
    for src in sources:
        m = _mapping(src)
        km = {str(k).lower(): k for k in m.keys()}
        for k in exact_l:
            if k in km:
                v = m[km[k]]
                if (not require_numeric) or (_numeric_or_none(v) is not None):
                    return v
    for src in sources:
        m = _mapping(src)
        for k, v in m.items():
            kl = str(k).lower()
            if any(e in kl for e in exclude_l):
                continue
            if any(f in kl for f in fallback_l):
                if (not require_numeric) or (_numeric_or_none(v) is not None):
                    return v
    raise KeyError(f"Unable to find value for {exact_keys}")

def _to_int(v):
    return int(round(float(v)))

